/// <summary>
/// class METGUPItemBasePriceCalcDialogEventHandler
/// </summary>
internal final class METGUPItemBasePriceCalcDialogEventHandler
{
}

Method.Source:
/// <summary>
/// Modified
/// </summary>
/// <param name = "_sender">form control</param>
/// <param name = "_e">form control event args</param>
[FormControlEventHandler(formControlStr(GUPItemBasePriceCalcDialog, BasePriceActivatePrice), FormControlEventType::Modified),
    SuppressBPWarningAttribute('BPParameterNotUsed', "@MET:BPParameterNotUsedMessage")]
public static void BasePriceActivatePrice_OnModified(FormControl _sender, FormControlEventArgs _e)
{
    FormCheckBoxControl control = _sender as FormCheckBoxControl;
    _sender.formRun().control(_sender.formRun().controlId(formControlStr(GUPItemBasePriceCalcDialog, GeneratePriceChangeInquiry))).visible(control.checked());
    _sender.formRun().control(_sender.formRun().controlId(formControlStr(GUPItemBasePriceCalcDialog, METIncludeClaimFromVendor))).visible(control.checked());
}

/// <summary>
/// Activated
/// </summary>
/// <param name = "_sender">form run</param>
/// <param name = "_e">form event args</param>
[FormEventHandler(formStr(GUPItemBasePriceCalcDialog), FormEventType::Activated),
    SuppressBPWarningAttribute('BPParameterNotUsed', "@MET:BPParameterNotUsedMessage")]
public static void GUPItemBasePriceCalcDialog_OnActivated(xFormRun _sender, FormEventArgs _e)
{
    FormCheckBoxControl control = _sender.control(_sender.controlId(formControlStr(GUPItemBasePriceCalcDialog, BasePriceActivatePrice))) as FormCheckBoxControl;
    _sender.control(_sender.controlId(formControlStr(GUPItemBasePriceCalcDialog, GeneratePriceChangeInquiry))).visible(control.checked());
    _sender.control(_sender.controlId(formControlStr(GUPItemBasePriceCalcDialog, METIncludeClaimFromVendor))).visible(control.checked());
}
